def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """Count integers whose even/odd digit counts match and which are k-divisible."""
    def count_up_to(bound: int) -> int:
        if bound <= 0:
            return 0
        bound_digits = list(map(int, str(bound)))
        result = 0

        # Count each decimal length separately so that leading zeroes are never
        # interpreted as digits of the number.
        for length in range(1, len(bound_digits) + 1):
            digits = bound_digits if length == len(bound_digits) else [9] * length

            @lru_cache(None)
            def dp(pos: int, balance: int, remainder: int, tight: bool) -> int:
                if pos == length:
                    return int(balance == 0 and remainder == 0)
                upper = digits[pos] if tight else 9
                total = 0
                for digit in range(1 if pos == 0 else 0, upper + 1):
                    total += dp(
                        pos + 1,
                        balance + (1 if digit % 2 == 0 else -1),
                        (remainder * 10 + digit) % k,
                        tight and digit == upper,
                    )
                return total

            result += dp(0, 0, 0, True)
        return result

    return count_up_to(high) - count_up_to(low - 1)"}
